skip_unless_brms_suite()
epilepsy <- brms::epilepsy
inhaler <- brms::inhaler

test_that("default_prior finds all classes for which priors can be specified", {
  brms_port("priors:5", "divergence",
    paste0(
      "frmtmb lists 5 class theta rows (its covariance parameters) ",
      "and no per-coefficient sd rows, since its class sd ",
      "addresses a block and refuses coef (priorform ledger P1)"),
    expect_equal(
      sort(
        default_prior(
          count ~ zBase * Trt + (1|patient) + (1+Trt|visit),
          data = epilepsy, family = "poisson"
        )$class
      ),
      sort(c(rep("b", 4), c("cor", "cor"), "Intercept", rep("sd", 6)))
    )
  )
  brms_port("priors:14", "cannot transfer",
    paste0(
      "sratio() takes no threshold = 'equidistant' and there is no ",
      "cse() alias (priorform ledger P2)"),
    expect_equal(
      sort(
        default_prior(
          rating ~ treat + period + cse(carry), data = inhaler,
          family = sratio(threshold = "equidistant")
        )$class
      ),
      sort(c(rep("b", 4), "delta", rep("Intercept", 1)))
    )
  )
})

test_that("set_prior allows arguments to be vectors", {
  brms_setup("priors:26",
    bprior <- set_prior("normal(0, 2)", class = c("b", "sd"))
  )
  brms_port("priors:27", "divergence",
    paste0(
      "expect_is(bprior, 'brmsprior'): the object is a ",
      "frmtmb_priorlist; brms's class name; frmtmb objects must ",
      "NOT carry brms's class names (user decision, 2026-09-17, ",
      "rule 2)"),
    expect_is(bprior, "brmsprior")
  )
  brms_port("priors:28", "pass",
    "",
    expect_equal(bprior$prior, rep("normal(0, 2)", 2))
  )
  brms_port("priors:29", "pass",
    "",
    expect_equal(bprior$class, c("b", "sd"))
  )
})

