test_that("prior tags are correctly applied", {
  brms_setup("priors:145",
    prior1 <- prior(normal(0, 1), class = sd, tag = "prior_tag1")
  )
  brms_setup("priors:146",
    prior2 <- prior(normal(0, 5), class = b, tag = "prior_tag2")
  )
  brms_setup("priors:147",
    prior3 <- prior(normal(0, 0.5), coef = "Trt1", tag = "prior_tag3")
  )
  brms_setup("priors:148",
    prior4 <- prior(normal(0, 10), class = "Intercept", tag = "prior_tag4")
  )
  brms_setup("priors:149",
    prior5 <- prior(lkj_corr_cholesky(3), class = "L", group = "visit", 
        tag = "prior_tag5")
  )
  brms_setup("priors:151",
    v <- validate_prior(
      c(prior1, prior2, prior3, prior4, prior5),
      formula = count ~ zBase * Trt + (1 | patient) + (1 + Trt | visit),
      data = epilepsy, family = poisson())
  )
  brms_port("priors:156", "cannot transfer",
    paste0(
      "set_prior() takes no tag: a tag names a prior inside a Stan ",
      "program (priorform ledger P33)"),
    expect_equal(v[which(v$class == "sd"),]$tag[[1]], "prior_tag1")
  )
  brms_port("priors:157", "cannot transfer",
    "set_prior() takes no tag (priorform ledger P34)",
    expect_equal(v[which(v$class == "b" & v$coef != "Trt1"), ]$tag[[1]], 
        "prior_tag2")
  )
  brms_port("priors:158", "cannot transfer",
    "set_prior() takes no tag (priorform ledger P35)",
    expect_equal(v[which(v$class == "b" & v$coef == "Trt1"),]$tag, "prior_tag3")
  )
  brms_port("priors:159", "cannot transfer",
    "set_prior() takes no tag (priorform ledger P36)",
    expect_equal(v[which(v$class == "Intercept"),]$tag, "prior_tag4")
  )
  brms_port("priors:160", "cannot transfer",
    "set_prior() takes no tag (priorform ledger P37)",
    expect_equal(v[which(v$class == "L"),]$tag[[2]], "prior_tag5")
  )
})
